pub async fn caption_read(path:String)->Result<String>{let privacy_epoch=crate::privacy::epoch();let privacy_result=(async {tauri::async_runtime::spawn_blocking(move||{let p=Path::new(&path);if p.extension().and_then(|s|s.to_str()).is_none_or(|s|!s.eq_ignore_ascii_case("srt")){return Err("project_path".into());}let mut f=gallery::lock_file(p)?;if f.metadata().map_err(err)?.len()>1024*1024{return Err("creative_limit".into());}let mut text=String::new();f.read_to_string(&mut text).map_err(err)?;Ok(text)}).await.map_err(err)?}).await;crate::privacy::finish(privacy_epoch,privacy_result)}
