pub struct VideoJob {pub id:String,pub name:String,pub status:String,pub progress:f64,pub error:Option<String>,pub output:Option<String>,pub preview:bool,pub directory:String,pub project_id:String,pub timeline:Timeline,pub format:String,pub bitrate:u32}
pub struct VideoEngine {media:media::MediaTools,state:Mutex<(Connection,Vec<VideoJob>)>,runtime:PathBuf,busy:AtomicBool,cancel:AtomicBool}
impl VideoEngine {
 pub fn new(config:&Path,runtime:PathBuf)->Result<Arc<Self>>{let db=Connection::open(config.join("video-jobs.sqlite3")).map_err(err)?;db.execute_batch("PRAGMA journal_mode=WAL; CREATE TABLE IF NOT EXISTS video_jobs(id TEXT PRIMARY KEY,json TEXT NOT NULL); CREATE TABLE IF NOT EXISTS media_cache(id TEXT PRIMARY KEY,json TEXT NOT NULL)").map_err(err)?;let jobs={let mut q=db.prepare("SELECT json FROM video_jobs ORDER BY rowid DESC LIMIT 30").map_err(err)?;let rows=q.query_map([],|r|r.get::<_,String>(0)).map_err(err)?;let mut jobs=vec![];for row in rows{let mut j:VideoJob=serde_json::from_str(&row.map_err(err)?).map_err(err)?;if j.status=="running"{j.status="interrupted".into();j.error=Some("video_interrupted".into());}jobs.push(j);}jobs};Ok(Arc::new(Self{state:Mutex::new((db,jobs)),media:media::MediaTools::new(),runtime,busy:AtomicBool::new(false),cancel:AtomicBool::new(false)}))}
 pub fn stop(&self){self.media.stop();self.cancel.store(true,Ordering::SeqCst);}
 fn update(&self,id:&str,mutate:impl FnOnce(&mut VideoJob)){if let Ok(mut s)=self.state.lock(){if let Some(j)=s.1.iter_mut().find(|j|j.id==id){mutate(j);let text=serde_json::to_string(j).unwrap_or_default();let _=s.0.execute("INSERT OR REPLACE INTO video_jobs VALUES(?1,?2)",rusqlite::params![id,text]);}}}
 pub(crate) fn runtime(&self)->Result<(PathBuf,Vec<File>)>{let manifest:serde_json::Value=serde_json::from_str(include_str!("../../../video-runtime.json")).map_err(err)?;let mut pins=gallery::directory_guards(&self.runtime)?;for (name,hash) in manifest["files"].as_object().ok_or("video_runtime")?{if name.contains(['/', '\\', ':']){return Err("video_runtime".into());}let mut f=gallery::lock_file(&self.runtime.join(name)).map_err(|_|"video_runtime")?;if digest(&mut f)?!=hash.as_str().unwrap_or(""){return Err("video_runtime".into());}pins.push(f);}Ok((self.runtime.clone(),pins))}
}
