pub struct Probe {pub duration:f64,pub width:u32,pub height:u32,pub audio:bool,pub video:bool}
fn command(path:&Path)->Command{let mut c=Command::new(path);c.creation_flags(0x08000000).stdin(Stdio::null());c}
fn capture(mut c:Command)->Result<Vec<u8>>{let mut child=c.stdout(Stdio::piped()).stderr(Stdio::null()).spawn().map_err(|_|"video_runtime")?;let guard=match crate::image_engine::ProcessGroup::attach(&child){Ok(g)=>g,Err(e)=>{let _=child.kill();let _=child.wait();return Err(e);}};let mut pipe=child.stdout.take().ok_or("video_runtime")?;let reader=thread::spawn(move||{let mut b=vec![];let _=(&mut pipe).take(1024*1024).read_to_end(&mut b);b});let start=Instant::now();let status=loop{if let Some(s)=child.try_wait().map_err(err)?{break s;}if start.elapsed()>Duration::from_secs(30){let _=child.kill();let _=child.wait();return Err("video_timeout".into());}thread::sleep(Duration::from_millis(30));};drop(guard);let bytes=reader.join().map_err(|_|"video_runtime")?;if !status.success(){return Err("video_decode".into());}Ok(bytes)}
pub(crate) fn probe(runtime:&Path,path:&Path)->Result<Probe>{let mut c=command(&runtime.join("ffprobe.exe"));c.args(["-v","error","-protocol_whitelist","file,pipe","-format_whitelist","mov,matroska,webm,mp3,wav,flac,ogg,image2,png_pipe,jpeg_pipe,bmp_pipe","-show_entries","format=duration:stream=codec_type,width,height,duration","-of","json"]).arg(path);let j:serde_json::Value=serde_json::from_slice(&capture(c)?).map_err(|_|"video_decode")?;let streams=j["streams"].as_array().ok_or("video_decode")?;let v=streams.iter().find(|s|s["codec_type"]=="video");let duration=j["format"]["duration"].as_str().and_then(|s|s.parse::<f64>().ok()).unwrap_or(0.);if !duration.is_finite()||duration>86400.{return Err("video_decode".into());}Ok(Probe{duration,width:v.and_then(|v|v["width"].as_u64()).unwrap_or(0) as u32,height:v.and_then(|v|v["height"].as_u64()).unwrap_or(0) as u32,audio:streams.iter().any(|s|s["codec_type"]=="audio"),video:v.is_some()})}
pub(super) fn duration(t:&Timeline)->f64{t.clips.iter().map(|c|c.start+(c.source_out-c.source_in)/c.speed).chain(t.captions.iter().map(|c|c.end)).fold(0.,f64::max)}
fn number(x:f64)->String{format!("{x:.6}")}
fn expression(keys:&[Keyframe],get:fn(&Keyframe)->f64,time:&str)->String{let mut value=number(get(keys.last().unwrap()));for pair in keys.windows(2).rev(){let(a,b)=(&pair[0],&pair[1]);let line=format!("{}+({})*({time}-{})/{}",number(get(a)),number(get(b)-get(a)),number(a.time),number(b.time-a.time));value=format!("if(lt({time},{}),{line},{value})",number(b.time));}value}
