 let mut f=format!("[{i}:v]trim=start={}:end={},setpts=(PTS-STARTPTS)/{},fps={},scale=w='max(2,trunc({iw}*({scale})/2)*2)':h='max(2,trunc({ih}*({scale})/2)*2)':eval=frame,setsar=1,format=rgba,lutrgb=r='clip((val-128)*{contrast}+128+255*{brightness},0,255)':g='clip((val-128)*{contrast}+128+255*{brightness},0,255)':b='clip((val-128)*{contrast}+128+255*{brightness},0,255)',hue=s={saturation}",number(if frame{0.}else{clip.source_in}),number(if frame{0.1}else{clip.source_out}),number(if frame{1.}else{clip.speed}),t.fps,brightness=number(clip.brightness),contrast=number(clip.contrast),saturation=number(clip.saturation));
 if clip.blur>0.{f.push_str(&format!(",gblur=sigma={}",number(clip.blur)));}f.push_str(&format!(",rotate=angle='({rotate})*PI/180':ow='ceil(hypot(iw,ih)/2)*2':oh=ow:c=none,format=rgba,geq=r='r(X,Y)':g='g(X,Y)':b='b(X,Y)':a='alpha(X,Y)*({alpha})'"));if clip.fade_in>0.{f.push_str(&format!(",fade=t=in:st=0:d={}:alpha=1",number(clip.fade_in)));}if clip.fade_out>0.{f.push_str(&format!(",fade=t=out:st={}:d={}:alpha=1",number(len-clip.fade_out),number(clip.fade_out)));}f.push_str(&format!(",setpts=PTS+{}/TB[clip{i}]",number(clip.start)));filters.push(f);
