fn execute(engine:&VideoEngine,p:Project,job:&VideoJob,gallery_root:&Path)->Result<String>{
 let(runtime,_runtime_pins)=engine.runtime()?;let work=Path::new(&job.directory);let _pins=gallery::directory_guards(work)?;let mut sources=vec![];let mut probes=vec![];for clip in &job.timeline.clips{if engine.cancel.load(Ordering::SeqCst){return Err("video_cancelled".into());}let source=Projects::creative_source(&p,&clip.asset_id)?;let probed=probe(&runtime,&source.1)?;if probed.width>16384||probed.height>16384{return Err("creative_limit".into());}probes.push(probed);sources.push(source);}
 let log=OpenOptions::new().write(true).create_new(true).open(work.join("render.log")).map_err(err)?;let mut c=build(&job.timeline,&sources,&probes,work,&job.format,job.bitrate,job.preview,&runtime,false)?;let mut child=c.stdout(Stdio::piped()).stderr(log).spawn().map_err(|_|"video_runtime")?;let _guard=match crate::image_engine::ProcessGroup::attach(&child){Ok(g)=>g,Err(e)=>{let _=child.kill();let _=child.wait();return Err(e);}};let pipe=child.stdout.take().ok_or("video_runtime")?;let(tx,rx)=std::sync::mpsc::channel();let reader=thread::spawn(move||{for line in BufReader::new(pipe).lines().map_while(std::result::Result::ok){if let Some(s)=line.strip_prefix("out_time_us="){if let Ok(v)=s.parse::<f64>(){let _=tx.send(v/1e6);}}}});let start=Instant::now();let total=duration(&job.timeline);let status=loop{if engine.cancel.load(Ordering::SeqCst)||start.elapsed()>Duration::from_secs(4*3600){let _=child.kill();let _=child.wait();let _=reader.join();return Err(if engine.cancel.load(Ordering::SeqCst){"video_cancelled"}else{"video_timeout"}.into());}for time in rx.try_iter(){engine.update(&job.id,|j|j.progress=(time/total).clamp(0.,0.99));}if let Some(s)=child.try_wait().map_err(err)?{break s;}thread::sleep(Duration::from_millis(80));};let _=reader.join();if !status.success(){return Err("video_encode".into());}
 let output=work.join(format!("render.{}",job.format));let check=probe(&runtime,&output)?;if !check.video||!check.audio||check.duration<total-0.15{return Err("video_encode".into());}if engine.cancel.load(Ordering::SeqCst){return Err("video_cancelled".into());}
 if project_restricted(&p){crate::privacy::mark(&output)?;}if job.preview{return Ok(output.to_string_lossy().into());}let name=format!("Timeline-{}.{}",&job.id[..8],job.format);let path=gallery::copy_one_named(gallery_root,gallery_root,&output,&name)?;Ok(gallery_root.join(path).to_string_lossy().into())
}
