pub fn protocol(ctx:tauri::UriSchemeContext<'_,tauri::Wry>,req:Request<Vec<u8>>,responder:tauri::UriSchemeResponder){let e=ctx.app_handle().state::<Arc<VideoEngine>>().inner().clone();let label=ctx.webview_label().to_string();tauri::async_runtime::spawn_blocking(move||{let result=(||{if label!="main"{return None;}let id=req.uri().path().trim_matches('/');let s=e.state.lock().ok()?;let j=s.1.iter().find(|j|j.id==id&&j.status=="completed")?;let output=PathBuf::from(j.output.as_ref()?);let root=fs::canonicalize(output.parent()?).ok()?;let name=output.file_name()?.to_str()?;let(mut parts,body)=req.into_parts();parts.uri=format!("/{}/{}",gallery::root_id(&root),base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(name)).parse().ok()?;Some(gallery::response(&root,&label,Request::from_parts(parts,body)))})();responder.respond(result.unwrap_or_else(||Response::builder().status(404).body(vec![]).unwrap()));});}
#[cfg(test)]mod tests{use super::*;#[test]fn keyframe_interpolation_is_numeric_and_duration_accounts_for_speed(){let k=Keyframe{time:0.,x:0.,y:0.,scale:1.,rotation:0.,opacity:1.,volume:1.};let mut end=k.clone();end.time=2.;end.x=100.;assert!(expression(&[k,end],|k|k.x,"t").contains("100.000000"));assert_eq!(number(1.5),"1.500000");}}
